fn state_machine_tasks() -> [V2TaskSpec; 10] {
    [
        V2TaskSpec {
            id: "v2_fsm_tcp_lifecycle",
            category: "state_machine",
            description: "Implement `tcp_fsm(events)` starting in `\"CLOSED\"` and processing `[\"LISTEN\", \"SYN\", \"ACK\", \"FIN\", \"CLOSE\"]`: `CLOSED + LISTEN -> LISTEN`, `LISTEN + SYN -> SYN_RCVD`, `CLOSED + SYN -> SYN_SENT`, `SYN_RCVD + ACK -> ESTABLISHED`, `SYN_SENT + ACK -> ESTABLISHED`, `ESTABLISHED + FIN -> CLOSE_WAIT`, `CLOSE_WAIT + CLOSE -> CLOSED`. Return `\"INVALID\"` immediately on any unmapped event.",
            signature: "fn tcp_fsm(events: list[str]) to str",
            expected: &["fn tcp_fsm"],
            answer: "fn tcp_fsm(events: list[str]) to str {\n    let mut st: str = \"CLOSED\"\n    for ev in events {\n        if st == \"CLOSED\" and ev == \"LISTEN\" { st = \"LISTEN\" }\n        else if st == \"LISTEN\" and ev == \"SYN\" { st = \"SYN_RCVD\" }\n        else if st == \"CLOSED\" and ev == \"SYN\" { st = \"SYN_SENT\" }\n        else if (st == \"SYN_RCVD\" or st == \"SYN_SENT\") and ev == \"ACK\" { st = \"ESTABLISHED\" }\n        else if st == \"ESTABLISHED\" and ev == \"FIN\" { st = \"CLOSE_WAIT\" }\n        else if st == \"CLOSE_WAIT\" and ev == \"CLOSE\" { st = \"CLOSED\" }\n        else { return \"INVALID\" }\n    }\n    return st\n}",
            harness: "fn __vox_eval_harness() to str {\n    assert(tcp_fsm([\"LISTEN\", \"SYN\", \"ACK\", \"FIN\", \"CLOSE\"]) == \"CLOSED\")\n    assert(tcp_fsm([\"SYN\", \"ACK\"]) == \"ESTABLISHED\")\n    assert(tcp_fsm([\"LISTEN\", \"ACK\"]) == \"INVALID\")\n    return \"ok\"\n}",
            wrong_stub: "fn tcp_fsm(events: list[str]) to str { return \"__wrong__\" }",
        },
        V2TaskSpec {
            id: "v2_fsm_turnstile",
            category: "state_machine",
            description: "Implement `simulate_turnstile(inputs)` starting locked: `\"coin\"` unlocks (if locked) or wastes nothing (`unlocks` stays); `\"push\"` when unlocked increments entry count and locks again; `\"push\"` when locked increments rejected count. Return `[entries, rejected]`.",
            signature: "fn simulate_turnstile(inputs: list[str]) to list[int]",
            expected: &["fn simulate_turnstile"],
            answer: "fn simulate_turnstile(inputs: list[str]) to list[int] {\n    let mut locked: bool = true\n    let mut entries: int = 0\n    let mut rejected: int = 0\n    for op in inputs {\n        if op == \"coin\" {\n            locked = false\n        } else if op == \"push\" {\n            if locked {\n                rejected = rejected + 1\n            } else {\n                entries = entries + 1\n                locked = true\n            }\n        }\n    }\n    return [entries, rejected]\n}",
            harness: "fn __vox_eval_harness() to str {\n    assert(simulate_turnstile([\"push\", \"coin\", \"coin\", \"push\", \"push\"]) == [1, 2])\n    assert(simulate_turnstile([]) == [0, 0])\n    return \"ok\"\n}",
            wrong_stub: "fn simulate_turnstile(inputs: list[str]) to list[int] { return [999999] }",
        },
        V2TaskSpec {
            id: "v2_fsm_elevator",
            category: "state_machine",
            description: "Implement `elevator_final_floor(min_f, max_f, cmds)` starting at floor `0` (clamped inside `[min_f, max_f]`) processing `\"up\"`, `\"down\"`, and `\"goto:<n>\"` (ignoring out-of-range goto). Return final floor.",
            signature: "fn elevator_final_floor(min_f: int, max_f: int, cmds: list[str]) to int",
            expected: &["fn elevator_final_floor"],
            answer: "fn elevator_final_floor(min_f: int, max_f: int, cmds: list[str]) to int {\n    let mut floor: int = 0\n    if floor < min_f { floor = min_f }\n    if floor > max_f { floor = max_f }\n    for cmd in cmds {\n        if cmd == \"up\" {\n            if floor < max_f { floor = floor + 1 }\n        } else if cmd == \"down\" {\n            if floor > min_f { floor = floor - 1 }\n        } else if cmd.starts_with(\"goto:\") {\n            match cmd.slice(5, cmd.chars_count()).to_int() {\n                Some(target) => {\n                    if target >= min_f and target <= max_f { floor = target }\n                }\n                None => {}\n            }\n        }\n    }\n    return floor\n}",
            harness: "fn __vox_eval_harness() to str {\n    assert(elevator_final_floor(-2, 10, [\"down\", \"down\", \"down\", \"goto:7\", \"goto:99\", \"up\"]) == 8)\n    assert(elevator_final_floor(1, 5, [\"down\"]) == 1)\n    return \"ok\"\n}",
            wrong_stub: "fn elevator_final_floor(min_f: int, max_f: int, cmds: list[str]) to int { return -999999 }",
        },
        V2TaskSpec {
            id: "v2_fsm_traffic_light",
            category: "state_machine",
            description: "Implement `traffic_light_after(green_s, yellow_s, red_s, t)` returning `\"green\"`, `\"yellow\"`, or `\"red\"` at elapsed second `t >= 0` in the repeating cycle starting at `t = 0` with green.",
            signature: "fn traffic_light_after(green_s: int, yellow_s: int, red_s: int, t: int) to str",
            expected: &["fn traffic_light_after"],
            answer: "fn traffic_light_after(green_s: int, yellow_s: int, red_s: int, t: int) to str {\n    let cycle: int = green_s + yellow_s + red_s\n    let pos: int = t % cycle\n    if pos < green_s { return \"green\" }\n    if pos < green_s + yellow_s { return \"yellow\" }\n    return \"red\"\n}",
            harness: "fn __vox_eval_harness() to str {\n    assert(traffic_light_after(30, 5, 25, 0) == \"green\")\n    assert(traffic_light_after(30, 5, 25, 32) == \"yellow\")\n    assert(traffic_light_after(30, 5, 25, 45) == \"red\")\n    assert(traffic_light_after(30, 5, 25, 65) == \"green\")\n    return \"ok\"\n}",
            wrong_stub: "fn traffic_light_after(green_s: int, yellow_s: int, red_s: int, t: int) to str { return \"__wrong__\" }",
        },
        V2TaskSpec {
            id: "v2_fsm_atm_session",
            category: "state_machine",
            description: "Implement `run_atm(correct_pin, initial_balance, ops)` supporting `\"pin:<p>\"` (3 consecutive wrong pins permanently locks session), `\"withdraw:<amt>\"` (succeeds only when unlocked and `amt > 0 and amt <= bal`), returning final `[balance, locked_flag_0_or_1]`.",
            signature: "fn run_atm(correct_pin: str, initial_balance: int, ops: list[str]) to list[int]",
            expected: &["fn run_atm"],
            answer: "fn run_atm(correct_pin: str, initial_balance: int, ops: list[str]) to list[int] {\n    let mut bal: int = initial_balance\n    let mut authed: bool = false\n    let mut locked: bool = false\n    let mut fails: int = 0\n    for op in ops {\n        if locked { continue }\n        if op.starts_with(\"pin:\") {\n            let p: str = op.slice(4, op.chars_count())\n            if p == correct_pin {\n                authed = true\n                fails = 0\n            } else {\n                authed = false\n                fails = fails + 1\n                if fails >= 3 { locked = true }\n            }\n        } else if op.starts_with(\"withdraw:\") and authed {\n            match op.slice(9, op.chars_count()).to_int() {\n                Some(amt) => {\n                    if amt > 0 and amt <= bal { bal = bal - amt }\n                }\n                None => {}\n            }\n        }\n    }\n    if locked { return [bal, 1] }\n    return [bal, 0]\n}",
            harness: "fn __vox_eval_harness() to str {\n    assert(run_atm(\"1234\", 500, [\"withdraw:100\", \"pin:1234\", \"withdraw:200\", \"withdraw:400\"]) == [300, 0])\n    assert(run_atm(\"1234\", 500, [\"pin:0000\", \"pin:1111\", \"pin:2222\", \"pin:1234\", \"withdraw:50\"]) == [500, 1])\n    return \"ok\"\n}",
            wrong_stub: "fn run_atm(correct_pin: str, initial_balance: int, ops: list[str]) to list[int] { return [999999] }",
        },
        V2TaskSpec {
            id: "v2_fsm_vending_machine",
            category: "state_machine",
            description: "Implement `vending_trace(price, ops)` processing `\"coin:<c>\"`, `\"buy\"` (deducts `price` and emits `1` if balance >= price else `0`), and `\"refund\"` (emits remaining balance and resets balance to 0). Return emitted ints.",
            signature: "fn vending_trace(price: int, ops: list[str]) to list[int]",
            expected: &["fn vending_trace"],
            answer: "fn vending_trace(price: int, ops: list[str]) to list[int] {\n    let mut bal: int = 0\n    let mut out: list[int] = []\n    for op in ops {\n        if op.starts_with(\"coin:\") {\n            match op.slice(5, op.chars_count()).to_int() {\n                Some(c) => { if c > 0 { bal = bal + c } }\n                None => {}\n            }\n        } else if op == \"buy\" {\n            if bal >= price {\n                bal = bal - price\n                out = out.push(1)\n            } else {\n                out = out.push(0)\n            }\n        } else if op == \"refund\" {\n            out = out.push(bal)\n            bal = 0\n        }\n    }\n    return out\n}",
            harness: "fn __vox_eval_harness() to str {\n    assert(vending_trace(75, [\"coin:50\", \"buy\", \"coin:50\", \"buy\", \"refund\"]) == [0, 1, 25])\n    assert(vending_trace(100, [\"refund\"]) == [0])\n    return \"ok\"\n}",
            wrong_stub: "fn vending_trace(price: int, ops: list[str]) to list[int] { return [999999] }",
        },
        V2TaskSpec {
            id: "v2_fsm_circuit_breaker",
            category: "state_machine",
            description: "Implement `circuit_breaker_state(fail_thresh, events)` tracking consecutive `\"fail\"` vs `\"ok\"` and `\"probe_timeout\"`: starts `\"closed\"`; `fail_thresh` consecutive fails move `closed -> open`; `probe_timeout` moves `open -> half_open`; `ok` in `half_open -> closed`; `fail` in `half_open -> open`.",
            signature: "fn circuit_breaker_state(fail_thresh: int, events: list[str]) to str",
            expected: &["fn circuit_breaker_state"],
            answer: "fn circuit_breaker_state(fail_thresh: int, events: list[str]) to str {\n    let mut st: str = \"closed\"\n    let mut fails: int = 0\n    for ev in events {\n        if st == \"closed\" {\n            if ev == \"fail\" {\n                fails = fails + 1\n                if fails >= fail_thresh { st = \"open\" }\n            } else if ev == \"ok\" {\n                fails = 0\n            }\n        } else if st == \"open\" {\n            if ev == \"probe_timeout\" {\n                st = \"half_open\"\n            }\n        } else if st == \"half_open\" {\n            if ev == \"ok\" {\n                st = \"closed\"\n                fails = 0\n            } else if ev == \"fail\" {\n                st = \"open\"\n            }\n        }\n    }\n    return st\n}",
            harness: "fn __vox_eval_harness() to str {\n    assert(circuit_breaker_state(2, [\"fail\", \"ok\", \"fail\", \"fail\"]) == \"open\")\n    assert(circuit_breaker_state(2, [\"fail\", \"fail\", \"probe_timeout\", \"ok\"]) == \"closed\")\n    assert(circuit_breaker_state(2, [\"fail\", \"fail\", \"probe_timeout\", \"fail\"]) == \"open\")\n    return \"ok\"\n}",
            wrong_stub: "fn circuit_breaker_state(fail_thresh: int, events: list[str]) to str { return \"__wrong__\" }",
        },
        V2TaskSpec {
            id: "v2_fsm_token_bucket",
            category: "state_machine",
            description: "Implement `count_accepted_requests(capacity, refill_rate, req_times)` where tokens start full (`capacity`), refill by `(t - prev_t) * refill_rate` capped at `capacity` before each arrival timestamp `t`, and consume 1 token if >= 1 remains.",
            signature: "fn count_accepted_requests(capacity: int, refill_rate: int, req_times: list[int]) to int",
            expected: &["fn count_accepted_requests"],
            answer: "fn count_accepted_requests(capacity: int, refill_rate: int, req_times: list[int]) to int {\n    if req_times.len() == 0 or capacity <= 0 { return 0 }\n    let mut tokens: int = capacity\n    let mut prev_t: int = req_times[0].unwrap()\n    let mut accepted: int = 0\n    for t in req_times {\n        let dt: int = t - prev_t\n        if dt > 0 {\n            tokens = tokens + dt * refill_rate\n            if tokens > capacity { tokens = capacity }\n            prev_t = t\n        }\n        if tokens >= 1 {\n            tokens = tokens - 1\n            accepted = accepted + 1\n        }\n    }\n    return accepted\n}",
            harness: "fn __vox_eval_harness() to str {\n    assert(count_accepted_requests(2, 1, [0, 0, 0, 1, 1]) == 3)\n    assert(count_accepted_requests(3, 2, [0, 5, 5, 5, 5]) == 4)\n    assert(count_accepted_requests(1, 0, [0, 10]) == 1)\n    return \"ok\"\n}",
            wrong_stub: "fn count_accepted_requests(capacity: int, refill_rate: int, req_times: list[int]) to int { return -999999 }",
        },
        V2TaskSpec {
            id: "v2_fsm_undo_redo_buf",
            category: "state_machine",
            description: "Implement `eval_undo_redo(cmds)` supporting `\"append:<text>\"` (clears redo history), `\"undo\"`, and `\"redo\"`, starting from `\"\"` and returning the final buffer string.",
            signature: "fn eval_undo_redo(cmds: list[str]) to str",
            expected: &["fn eval_undo_redo"],
            answer: "fn eval_undo_redo(cmds: list[str]) to str {\n    let mut hist: list[str] = [\"\"]\n    let mut redo_st: list[str] = []\n    for cmd in cmds {\n        if cmd.starts_with(\"append:\") {\n            let txt: str = cmd.slice(7, cmd.chars_count())\n            let cur: str = hist[hist.len() - 1].unwrap()\n            hist = hist.push(cur + txt)\n            redo_st = []\n        } else if cmd == \"undo\" {\n            if hist.len() > 1 {\n                let top: str = hist[hist.len() - 1].unwrap()\n                hist = hist.remove_at(hist.len() - 1)\n                redo_st = redo_st.push(top)\n            }\n        } else if cmd == \"redo\" {\n            if redo_st.len() > 0 {\n                let val: str = redo_st[redo_st.len() - 1].unwrap()\n                redo_st = redo_st.remove_at(redo_st.len() - 1)\n                hist = hist.push(val)\n            }\n        }\n    }\n    return hist[hist.len() - 1].unwrap()\n}",
            harness: "fn __vox_eval_harness() to str {\n    assert(eval_undo_redo([\"append:ab\", \"append:cd\", \"undo\", \"redo\", \"undo\", \"append:xy\", \"redo\"]) == \"abxy\")\n    assert(eval_undo_redo([\"undo\", \"redo\"]) == \"\")\n    return \"ok\"\n}",
            wrong_stub: "fn eval_undo_redo(cmds: list[str]) to str { return \"__wrong__\" }",
        },
        V2TaskSpec {
            id: "v2_fsm_stopwatch",
            category: "state_machine",
            description: "Implement `stopwatch_elapsed(events)` tracking cumulative active milliseconds over `\"start:<t>\"`, `\"pause:<t>\"`, and `\"reset:<t>\"` (ignoring redundant start/pause; `reset:<t>` zeroes elapsed and pauses).",
            signature: "fn stopwatch_elapsed(events: list[str]) to int",
            expected: &["fn stopwatch_elapsed"],
            answer: "fn stopwatch_elapsed(events: list[str]) to int {\n    let mut running: bool = false\n    let mut start_t: int = 0\n    let mut acc: int = 0\n    for ev in events {\n        let parts: list[str] = ev.split(\":\")\n        let kind: str = parts[0].unwrap()\n        let t: int = parts[1].unwrap().to_int().unwrap()\n        if kind == \"start\" {\n            if not running {\n                running = true\n                start_t = t\n            }\n        } else if kind == \"pause\" {\n            if running {\n                acc = acc + (t - start_t)\n                running = false\n            }\n        } else if kind == \"reset\" {\n            acc = 0\n            running = false\n        }\n    }\n    return acc\n}",
            harness: "fn __vox_eval_harness() to str {\n    assert(stopwatch_elapsed([\"start:10\", \"start:20\", \"pause:35\", \"start:50\", \"pause:80\"]) == 55)\n    assert(stopwatch_elapsed([\"start:5\", \"pause:20\", \"reset:25\", \"start:30\", \"pause:42\"]) == 12)\n    return \"ok\"\n}",
            wrong_stub: "fn stopwatch_elapsed(events: list[str]) to int { return -999999 }",
        },
    ]
}

